  "Rasmiy kanal, kafolat va hujjat bilan. Diqqat: katalogda quyosh va 4G liniyasi ko'rsatilmagan — bu modellarni rasmiy olib kela oladimi, smeta tuzishdan oldin so'ralishi shart.": "Официальный канал, с гарантией и документами. Внимание: в каталоге линейка на солнечном питании и 4G не представлена — до составления сметы необходимо запросить, может ли компания официально поставить эти модели.",
