  "Toshkent va viloyatlar": "Ташкент и области",
  "Kalit topshirish tartibida montaj. Saytida internet yo'q joylar uchun SIM-kartali 4G va quyosh batareyali tizimlar ochiq e'lon qilingan. Smetada jihoz va ish haqi alohida ko'rsatiladi. Markazlashtirilgan 24/7 kuzatuv xizmati yo'q.": "Монтаж «под ключ». На сайте открыто заявлены системы с 4G SIM-картой и солнечными батареями для мест без интернета. В смете оборудование и стоимость работ указываются отдельно. Услуги централизованного наблюдения 24/7 отсутствуют.",
  "Longi, Jinko, Trina panellari": "Панели Longi, Jinko, Trina",
  "Quyosh panellari ombordan. Longi 575 Vt — 1 008 000 so'm, Jinko 560 Vt — 1 355 200 so'm, Trina 665 Vt — 1 625 120 so'm.": "Солнечные панели со склада. Longi 575 Вт — 1 008 000 сум, Jinko 560 Вт — 1 355 200 сум, Trina 665 Вт — 1 625 120 сум.",
  "+998 98 338-08-08 · Mirzo Ulug'bek 25": "+998 98 338-08-08 · Мирзо Улугбек 25",
  "560 Vt panel 800 000 so'mdan — topilgan takliflar ichida eng arzon vatt narxi. Firma asosan qurilish panellari bilan shug'ullanadi, kafolat va servis shartlari alohida tekshirilishi kerak.": "Панель 560 Вт от 800 000 сум — самая низкая цена ватта среди найденных предложений. Компания занимается преимущественно строительными панелями, условия гарантии и сервиса подлежат отдельной проверке.",
  "IIV huzuridagi Qo'riqlash departamenti": "Департамент охраны при МВД",
  "Butun respublika": "Вся республика",
  "Yagona qonuniy markazlashtirilgan kuzatuv kanali": "Единственный законный канал централизованного наблюдения",
  "Qonunga ko'ra shartnoma asosida qo'riqlash xizmatini faqat davlat organlari ko'rsatadi, xususiy kompaniyalar bu faoliyatni amalga oshira olmaydi. Departament trevoga tugmasi, yong'in signalizatsiyasi va telefon aloqasi yo'q hududlarda GSM kanali orqali qo'riqlashni taklif qiladi. 2025-yil noyabrda xizmat Milliy gvardiyadan IIV ga o'tkazildi.": "По закону охранные услуги на договорной основе оказывают только государственные органы, частные компании осуществлять эту деятельность не вправе. Департамент предлагает тревожную кнопку, пожарную сигнализацию, а в местностях без телефонной связи — охрану по GSM-каналу. В ноябре 2025 года служба передана из Национальной гвардии в МВД.",
  "WCCTV / WJ Sunstone — ijara modeli": "WCCTV / WJ Sunstone — модель аренды",
  "Xalqaro amaliyot": "Международная практика",
  "Jihozni sotib olish emas, ijaraga olish": "Не покупка оборудования, а его аренда",
  "Britaniyada bo'sh mulkni qo'riqlashning standart yechimi — ko'chma quyosh CCTV minorasini ijaraga olish. Minora 20 daqiqada ishga tushadi, obyekt sotilgach keyingisiga ko'chiriladi. Bank uchun bu kapital xarajat o'rniga oylik xizmat haqi degani.": "Стандартное решение по охране пустующей недвижимости в Великобритании — аренда мобильной вышки видеонаблюдения на солнечном питании. Вышка вводится в работу за 20 минут, после продажи объекта переносится на следующий. Для банка это означает ежемесячную плату за услугу вместо капитальных затрат.",
  "so'm/oy": "сум/мес.",
  "so'm/30 kun": "сум/30 дн.",
