  "Smeta: bitta obyekt va butun bosqich": "Смета: один объект и весь этап",
  "Jadval tahrirlanadi. Miqdor yoki narxni o'zgartirsangiz, yakuniy summa darhol qayta hisoblanadi. Narxlar jihoz qiymatiga o'rnatish, kabel-mahkamlagich va bojxona ustamasini qo'shib beriladi.": "Таблица редактируется. При изменении количества или цены итоговая сумма пересчитывается сразу. Цены приведены с учётом монтажа, кабельно-крепёжных материалов и таможенной надбавки к стоимости оборудования.",
  "dona": "шт.",
