  "Qoplanish": "Окупаемость",
  "Uch yo'lning uch yillik qiymati": "Стоимость трёх вариантов за три года",
  "Taqqoslash bitta o'rtacha obyekt uchun, uch yil muddatga. Qorovul varianti bir smenali post narxidan olingan; avtonom tizimda esa asosiy xarajat birinchi yilda bo'ladi, keyin faqat aloqa va xizmat qoladi.": "Сравнение приведено для одного среднего объекта на срок три года. Вариант со сторожем взят по стоимости односменного поста; в автономной системе основные затраты приходятся на первый год, далее остаются только связь и обслуживание.",
  "Tizim maket emas, u allaqachon ishlab turibdi": "Система не макет, она уже работает",
  "Quyidagi ekranlar ishlayotgan tizimdan olingan. Har bir ekranni ochib, o'z roli nomidan sinab ko'rish mumkin: reyestr, ko'rik, kirish nazorati, hisobotlar va rahbariyat paneli.": "Приведённые экраны сняты с действующей системы. Каждый экран можно открыть и проверить от имени своей роли: реестр, осмотры, контроль доступа, отчёты и панель руководства.",
  "Xarid yo'li": "Порядок закупки",
  "Huquqiy va xarid yo'li": "Правовой порядок и порядок закупки",
  "Yechim mavjud tartibga to'liq sig'adi: jihoz davlat xaridi orqali olinadi, qo'riqlash xizmati shartnoma bilan ulanadi, videoyozuv esa bankning o'z serverida saqlanadi.": "Решение полностью укладывается в действующий порядок: оборудование приобретается через государственные закупки, охранная служба подключается по договору, а видеозапись хранится на собственном сервере банка.",
  "Xatarlar": "Риски",
  "Beriladigan savollar va ularga javob": "Возможные вопросы и ответы на них",
  "Quyida loyihaning zaif joylari ochiq sanab o'tilgan. Har biri bo'yicha texnik javob va uni tekshirish usuli ko'rsatilgan.": "Ниже открыто перечислены слабые места проекта. По каждому приведены технический ответ и способ его проверки.",
  "Keyingi ufq": "Дальнейшая перспектива",
  "Bir xil jihozdan keyinroq nima olish mumkin": "Что можно получить позднее на том же оборудовании",
  "Quyidagilar pilot uchun shart emas. Ammo ular bir xil jihoz va bir xil ma'lumot ustiga qo'shiladi, shuning uchun bugungi tanlov ertangi imkoniyatni yopib qo'ymasligi kerak.": "Перечисленное не требуется для пилота. Однако оно надстраивается над тем же оборудованием и теми же данными, поэтому сегодняшний выбор не должен закрывать завтрашние возможности.",
  "Pilotni boshlash uchun to'rtta qaror yetarli": "Для запуска пилота достаточно четырёх решений",
  "Keyingi bosqichlar pilot natijasiga qarab alohida tasdiqlanadi. Pilot yakunida kengash aniq raqamlarni ko'radi: nechta hodisa qayd etildi, qancha xarajat tejaldi, sotuv qancha tezlashdi.": "Последующие этапы утверждаются отдельно по результатам пилота. По итогам пилота совет получит конкретные цифры: сколько происшествий зафиксировано, сколько затрат сэкономлено, насколько ускорилась продажа.",
