  "Ko'rsatilgan narx bitta obyekt uchun, o'rnatish va konstruksiya bilan. To'plam tarkibi pilot natijasiga ko'ra aniqlashtiriladi.": "Указанная цена приведена для одного объекта, с монтажом и конструкциями. Состав комплекта уточняется по результатам пилота.",
