  "Quvvat yetishmaydi": "Мощности недостаточно",
  "Hisob formulasi: kunlik ishlab chiqarish = panel quvvati × insolyatsiya × 0,72. Koeffitsient MPPT kontroller, chang, harorat, kabel va akkumulyator yo'qotishlarini qamraydi. Tanlangan daraja uchun dekabrda kerakli eng kam panel quvvati —": "Формула расчёта: суточная выработка = мощность панелей × инсоляция × 0,72. Коэффициент учитывает потери на контроллере MPPT, запылении, температуре, кабеле и аккумуляторе. Минимально необходимая мощность панелей в декабре для выбранного уровня —",
  ". Zavod to'plamlaridagi 3–18 Vt panellar yozgi hisobga tuzilgan va O'zbekiston qishida yetmaydi.": ". Панели 3–18 Вт из заводских комплектов рассчитаны на летние условия и зимой в Узбекистане недостаточны.",
