  "Zaxira yuki asosan sud va ijro bosqichidagi yozuvlar hisobiga o'sdi. Qoplash darajasi past obyektlar birinchi navbatda qayta baholanadi, auksonga chiqarilgan obyektlar bo'yicha zaxira realizatsiyadan so'ng qaytariladi.": "Резервная нагрузка выросла в основном за счёт записей на стадиях суда и исполнения. Объекты с низким покрытием переоцениваются в первую очередь; по выставленным на аукцион объектам резерв восстанавливается после реализации.",
