  "Tashrifchi obyektdan chiqishdan oldin quyidagi bandlar bandma-band tekshiriladi. Nomuvofiqlik topilsa hodisa avtomatik ochiladi va tashrif yopilmaydi.": "Перед выходом посетителя каждый пункт проверяется по отдельности. При несоответствии автоматически открывается происшествие, и посещение не закрывается.",
