  "Obyekt kartochkasi ekrani": "Экран карточки объекта",
  "Mulk reyestri ekrani": "Экран реестра имущества",
  "Portfel qiymati, hududlar xaritasi, qamrov, xarajat va hodisalar — rahbariyat uchun bitta ekran": "Стоимость портфеля, карта регионов, охват, расходы и инциденты — единый экран для руководства",
  "Kameralar devori, ochiq hodisalar oqimi, qurilmalar quvvati va aloqasi": "Видеостена, поток открытых инцидентов, заряд и связь устройств",
  "Obyekt pulsi, nazorat indeksi, hujjatlar, ko'riklar, xarajat va to'liq tarix": "Пульс объекта, индекс контроля, документы, осмотры, расходы и полная история",
  "Barcha mulk yagona ro'yxatda: qidiruv, filtrlar, CSV eksport": "Всё имущество в едином списке: поиск, фильтры, экспорт в CSV",
  "Joriy etish: avval pilot, keyin bosqichma-bosqich": "Внедрение: сначала пилот, затем поэтапно",
  "Yirik xariddan oldin yechim ikki hududdagi 10 ta obyektda sinab ko'riladi. Pilot yakunida qaror aniq raqamlar asosida qabul qilinadi.": "Прежде чем проводить крупную закупку, решение опробуется на 10 объектах в двух регионах. Результат пилота — возможность принять решение на основе точных цифр.",
  "Pilot": "Пилот",
  "6 hafta": "6 недель",
