  "C daraja va saqlash maydonchalari": "Уровень C и площадки хранения",
  "Sotilgan obyektdan jihoz keyingisiga ko'chiriladi": "Оборудование с реализованного объекта переносится на следующий",
  "Kadastr va soliq tizimlari bilan almashinuv": "Обмен с кадастровой и налоговой системами",
  "Rahbariyatga oylik avtomatik hisobot": "Ежемесячный автоматический отчёт руководству",
  "Ehtimoliy savollar va xatarlar": "Возможные вопросы и риски",
  "Hududda mobil aloqa sust bo'lsa-chi?": "Что делать, если в регионе слабая мобильная связь?",
  "Marshrutizator va markazda ikki operatorning SIM-kartasi turadi, tashqi yo'naltirilgan antenna qo'yiladi. Aloqa uzilganda kamera yozuvni xotira kartasida saqlaydi va tiklangach uzatadi; uzilishning o'zi hodisa sifatida qayd etiladi.": "В маршрутизаторе и централи установлены SIM-карты двух операторов, подключается внешняя направленная антенна. При обрыве связи камера сохраняет запись на карту памяти и передаёт её после восстановления; сам обрыв фиксируется как инцидент.",
  "Jihozning o'zi o'g'irlansa yoki sindirilsa?": "А если украдут или разобьют само оборудование?",
  "Kamera va panel 4–6 metr balandlikdagi ustunga, antivandal qutida o'rnatiladi. Korpus ochilsa yoki kamera burilsa, tizim darhol signal beradi. Jihoz sug'urtalanadi; yozuv bank serverida saqlangani uchun dalil yo'qolmaydi.": "Камера и панель монтируются на опоре высотой 4–6 метров, в антивандальном боксе. При вскрытии корпуса или повороте камеры система немедленно подаёт сигнал. Оборудование страхуется; поскольку запись хранится на сервере банка, доказательства не утрачиваются.",
  "Qishda quyosh kam bo'lganda tizim o'chib qolmaydimi?": "Не отключится ли система зимой, когда солнца мало?",
  "Panel va akkumulyator dekabr sharoiti uchun, 3 kunlik quyoshsiz zaxira bilan hisoblanadi (4-bo'limdagi kalkulyator). Quvvat 30% dan tushganda kamera tejamkor rejimga o'tadi, monitoring markazi esa oldindan ogohlantiriladi.": "Панель и аккумулятор рассчитываются на условия декабря, с запасом на 3 дня без солнца (калькулятор в разделе 4). При снижении заряда ниже 30% камера переходит в экономичный режим, а центр мониторинга получает предупреждение заранее.",
  "Ma'lumotlar xavfsizligi qanday ta'minlanadi?": "Как обеспечивается безопасность данных?",
  "Tizim va video arxiv bankning o'z serverida joylashadi. Qurilmalar yopiq APN yoki VPN orqali ulanadi, internetga to'g'ridan-to'g'ri chiqmaydi. Har bir foydalanuvchi faqat o'z roliga tegishli bo'limlarni ko'radi, barcha amallar jurnalga yoziladi.": "Система и видеоархив размещаются на собственном сервере банка. Устройства подключаются через закрытый APN или VPN и не имеют прямого выхода в интернет. Каждый пользователь видит только разделы, соответствующие его роли, все действия записываются в журнал.",
  "Hodisa yuz berganda obyektga kim boradi?": "Кто выезжает на объект при инциденте?",
  "Hududiy qo'riqlash xizmati bilan tezkor guruh chaqiruvi bo'yicha shartnoma tuziladi. Monitoring markazi navbatchisi hodisani kamera orqali tasdiqlagach, chaqiruv bir tugma bilan yuboriladi va hodisa kartochkasida qayd etiladi.": "С территориальной охранной службой заключается договор на вызов группы быстрого реагирования. После того как дежурный центра мониторинга подтвердит инцидент по камере, вызов направляется одной кнопкой и фиксируется в карточке инцидента.",
  "Rahbariyatdan so'raladigan qaror": "Решение, которое требуется от руководства",
  "Pilotni boshlash uchun to'rtta qaror yetarli. Keyingi bosqichlar pilot natijasiga qarab alohida tasdiqlanadi.": "Для запуска пилота достаточно четырёх решений. Остальные этапы согласовываются отдельно по результатам пилота.",
  "Pilotni tasdiqlash": "Утвердить пилот",
  "2 hudud, 10 obyekt, 6 hafta. Mas'ul — Muammoli aktivlar bilan ishlash departamenti.": "2 региона, 10 объектов, 6 недель. Ответственный — Департамент по работе с проблемными активами.",
