  "Nazorat indeksi, moliya, hujjatlar, ko'riklar, xarajatlar, qavat rejasi va 3D navigator": "Индекс контроля, финансы, документы, осмотры, расходы, поэтажный план и 3D-навигатор",
  "Kirish nazorati posti ishga tushadi": "Запускается пост контроля доступа",
