  "Tasdiqlangach obyekt «Balansda» bosqichiga o'tadi, qoldiq qarz summasi balans qiymati sifatida qayd etiladi, dalolatnoma raqami ish tarixiga yoziladi va saqlash xarajatlari hisobi ochiladi.": "После подтверждения объект переходит на этап «На балансе», сумма остатка долга фиксируется как балансовая стоимость, номер акта записывается в историю дела и открывается учёт расходов на содержание.",
