  "Obyektga elektr olib kirilmaydi. Jihoz quyosh energiyasida ishlaydi, aloqa 4G orqali, datchiklar o'z batareyasida. Qimmat obyektga to'liq to'plam, arzoniga ixcham to'plam qo'yiladi.": "Электричество на объект не подводится. Оборудование работает от солнечной энергии, связь — по 4G, датчики — на собственных батареях. На дорогой объект ставится полный комплект, на недорогой — компактный.",
