  "Panel va akkumulyator dekabr sharoiti uchun, 3 kunlik quyoshsiz zaxira bilan hisoblanadi (4-bo'limdagi kalkulyator). Quvvat 30% dan tushganda kamera tejamkor rejimga o'tadi, nazorat posti esa oldindan ogohlantiriladi.": "Панель и аккумулятор рассчитываются на декабрьские условия, с трёхдневным запасом без солнца (калькулятор в разделе 4). При заряде ниже 30% камера переходит в экономный режим, а пост контроля предупреждается заранее.",
  "Hududiy qo'riqlash xizmati bilan tezkor guruh chaqiruvi bo'yicha shartnoma tuziladi. Nazorat posti navbatchisi hodisani kamera orqali tasdiqlagach, chaqiruv bir tugma bilan yuboriladi va hodisa kartochkasida qayd etiladi.": "С территориальной охранной службой заключается договор на вызов группы быстрого реагирования. После того как дежурный поста контроля подтвердит происшествие по камере, вызов отправляется одной кнопкой и фиксируется в карточке происшествия.",
  "Olti rol: filial rahbari holatni ko'radi va tasdiqlaydi, menejer reyestrni yuritadi, inspektor ko'rik o'tkazadi va hodisalarga javob beradi, baholovchi va yurist o'z yo'nalishini yuritadi. Hisobot endi yig'ilmaydi — u doim tayyor.": "Шесть ролей: руководитель филиала видит состояние и согласовывает, менеджер ведёт реестр, инспектор проводит осмотры и реагирует на происшествия, оценщик и юрист ведут своё направление. Отчёт больше не собирают — он готов всегда.",
