  "FMB920 (olx.uz); TAT140 ≈ 66–131 € — olib kelishda 1,3–1,5 barobar oshadi ·": "FMB920 (olx.uz); TAT140 ≈ 66–131 € — при ввозе стоимость возрастает в 1,3–1,5 раза ·",
  "Bank infratuzilmasida joylashadi; qiymat IT bo'limi bilan aniqlanadi ·": "Размещается в инфраструктуре банка; стоимость определяется совместно с ИТ-подразделением ·",
  "Narxlar 2026-yil sentabr holatiga. Rasmiy hisob-faktura bilan xarid qilinganda narx 12–20% ga oshishi mumkin. Yakuniy tanlov kamida uchta rasmiy yetkazib beruvchidan taklif olingandan keyin qilinadi.": "Цены приведены по состоянию на сентябрь 2026 года. При закупке с оформлением официального счёта-фактуры стоимость может возрасти на 12–20%. Окончательный выбор производится после получения предложений не менее чем от трёх официальных поставщиков.",
  "Ro'yxat bozorda ochiq e'lon qilingan ma'lumot asosida tuzilgan va tavsiya emas. Qonunga ko'ra shartnoma asosida qo'riqlash xizmatini faqat davlat organlari ko'rsatadi, shuning uchun markazlashtirilgan kuzatuv bo'yicha yagona yo'l — Ichki ishlar vazirligi huzuridagi Qo'riqlash departamenti.": "Перечень составлен на основании общедоступных сведений и не является рекомендацией. Согласно законодательству, услуги охраны на договорной основе оказывают исключительно государственные органы, поэтому единственным каналом централизованного наблюдения является Департамент охраны при Министерстве внутренних дел.",
  "Narxlar 2026-yil sentabr holatiga, so'mda. Import qatorlari ko'rsatilgan kurs bo'yicha o'giriladi. «Taxminiy» belgisi qo'yilgan qatorlar ochiq narxga ega emas va kotirovka bo'yicha aniqlanadi. Smetaga kirmagan va alohida hisoblanadigan qatorlar: mahalliy yozuv serveri, markazlashtirilgan kuzatuvga ulanish abonent to'lovi va yillik texnik xizmat.": "Цены приведены по состоянию на сентябрь 2026 года, в сумах. Импортные позиции пересчитываются по указанному курсу. Позиции с отметкой «ориентировочно» не имеют открытой цены и определяются по коммерческому предложению. В смету не включены и рассчитываются отдельно: локальный сервер видеозаписи, абонентская плата за подключение к централизованному наблюдению и ежегодное техническое обслуживание.",
